package br.casasala.painel;
import java.io.InputStream;import java.io.ByteArrayOutputStream;import java.util.HashSet;import org.json.JSONObject;import org.json.JSONArray;import org.json.JSONTokener;
/** Bounded, atomic configuration import. Validation never opens a device socket. */
public final class DeviceImport{
 public static JSONObject read(InputStream input,JSONArray existing)throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=input.read(b))!=-1){if(out.size()+n>1048576)throw new Exception("Arquivo maior que 1 MB.");out.write(b,0,n);}String text=new String(out.toByteArray(),"UTF-8");if(text.startsWith("\ufeff"))text=text.substring(1);return parse(text,existing);}
 public static JSONObject parse(String text,JSONArray existing)throws Exception{Object raw;try{JSONTokener tokenizer=new JSONTokener(text);raw=tokenizer.nextValue();if(tokenizer.nextClean()!=0)throw new Exception();}catch(Exception malformed){throw new Exception("Arquivo JSON inválido. Nenhum cadastro foi alterado.");}JSONArray source;if(raw instanceof JSONArray)source=(JSONArray)raw;else if(raw instanceof JSONObject){JSONObject top=(JSONObject)raw;if(top.has("schema")&&!"painel-tuya".equals(top.optString("schema")))throw new Exception("Formato de arquivo desconhecido.");if(top.optInt("version",1)!=1)throw new Exception("Versão do arquivo não suportada.");source=top.optJSONArray("devices");}else source=null;
  if(source==null||source.length()==0||source.length()>200)throw new Exception("O arquivo precisa conter entre 1 e 200 dispositivos.");JSONArray merged=new JSONArray();for(int i=0;i<existing.length();i++)merged.put(new JSONObject(existing.getJSONObject(i).toString()));HashSet<String> seen=new HashSet<String>();int added=0,updated=0;
  String[] fields={"name","room","ip","version","switch_dp","mode_dp","brightness_dp","temperature_dp","color_dp","brightness_min","brightness_max","color_format","light_profile"};
  for(int i=0;i<source.length();i++){JSONObject row=source.optJSONObject(i);if(row==null)throw new Exception("Item "+(i+1)+": dispositivo inválido.");JSONObject device=new JSONObject();for(int k=0;k<fields.length;k++)if(row.has(fields[k]))device.put(fields[k],row.get(fields[k]));String physical=row.optString("device_id",row.optString("id"));device.put("device_id",physical).put("local_key",row.optString("local_key",row.optString("key")));if(!device.has("name"))device.put("name","Lâmpada "+(i+1));if(!device.has("room"))device.put("room","Casa");
   try{String ip=device.optString("ip");String[] parts=ip.split("\\.");if(parts.length!=4)throw new Exception();for(int k=0;k<4;k++){int value=Integer.parseInt(parts[k]);if(value<0||value>255)throw new Exception();}TuyaLan.validate(device);if(LightingProfile.enabled(device))LightingProfile.validate(device);}catch(Exception error){throw new Exception("Item "+(i+1)+": confira IP, ID, chave de 16 bytes, protocolo e DPs.");}
   String identity=physical+":"+device.getString("switch_dp");if(!seen.add(identity))throw new Exception("Item "+(i+1)+": dispositivo/canal repetido.");int found=-1;for(int k=0;k<merged.length();k++){JSONObject old=merged.getJSONObject(k);if(physical.equals(old.optString("device_id"))&&device.getString("switch_dp").equals(old.optString("switch_dp")))found=k;}
   if(found>=0){device.put("id",merged.getJSONObject(found).getString("id"));merged.put(found,device);updated++;}else{device.put("id","tuya-"+physical+"-"+device.getString("switch_dp"));merged.put(device);added++;}
  }return new JSONObject().put("devices",merged).put("added",added).put("updated",updated).put("count",source.length());
 }
}
